                    []
                ]
                input[1] = [ [:], [] ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.cov[0][1] ==~ ".*/test.bed" },
                { assert snapshot(
                    process.out.cov,
                    process.out.findAll { key, val -> key.startsWith("versions") }
